<?php
namespace App\Http\Controllers;
use App\Services\AuditLogger;
use App\Services\CoreClient;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Gate;
use Inertia\Inertia;
class SynapseUserController {
 public function __construct(private CoreClient $core,private AuditLogger $audit) {}
 private function id(string $id): string { return rawurlencode($id); }
 private function supportsLocked(): bool { try{$version=$this->core->request('GET','/api/v1/server/version');return version_compare((string)($version['server_version']??''),'1.93.0','>=');}catch(\Throwable $e){return false;} }
 public function index(Request $r) { Gate::authorize('synapse-users-view');$supportsLocked=$this->supportsLocked();$query=$r->only(['from','limit','name','user_id','guests','admins','deactivated','locked','order_by','dir']);if(!$supportsLocked)unset($query['locked']);try{$result=$this->core->request('GET','/api/v1/users',$query);$error=null;}catch(\Throwable $e){$result=['users'=>[],'total'=>0,'next_token'=>null];$error=$e->getMessage();}return Inertia::render('Users/Index',['result'=>$result,'filters'=>$query,'error'=>$error,'supportsLocked'=>$supportsLocked]);}
 public function show(Request $r,string $userID) { Gate::authorize('synapse-users-view');$id=$this->id($userID);$user=$this->core->request('GET',"/api/v1/users/$id");$devices=$this->core->request('GET',"/api/v1/users/$id/devices");$rooms=$this->core->request('GET',"/api/v1/users/$id/joined-rooms");$whois=null;if(Gate::allows('view-whois')){$whois=$this->core->request('GET',"/api/v1/users/$id/whois");$this->audit->record($r,'synapse.user.whois.view','matrix_user',$userID);}$media=$this->core->request('GET',"/api/v1/users/$id/media",['limit'=>100]);$mediaUsage=$this->core->request('GET',"/api/v1/users/$id/media-usage");$ratelimit=$this->core->request('GET',"/api/v1/users/$id/ratelimit");return Inertia::render('Users/Show',['user'=>$user,'devices'=>$devices,'rooms'=>$rooms,'whois'=>$whois,'media'=>$media,'mediaUsage'=>$mediaUsage,'ratelimit'=>$ratelimit,'supportsLocked'=>$this->supportsLocked()]);}
 public function store(Request $r) { Gate::authorize('synapse-users-update');$data=$r->validate(['user_id'=>'required|string|max:255','password'=>'required|string|min:12|max:255','displayname'=>'nullable|string|max:255','admin'=>'sometimes|boolean','deactivated'=>'sometimes|boolean','locked'=>'sometimes|boolean']);$userID=$data['user_id'];unset($data['user_id']);if(!$this->supportsLocked())unset($data['locked']);$this->core->request('PUT','/api/v1/users/'.$this->id($userID),[],$data);$this->audit->record($r,'synapse.user.create','matrix_user',$userID,['displayname'=>$data['displayname']??null,'admin'=>$data['admin']??false,'deactivated'=>$data['deactivated']??false,'locked'=>$data['locked']??false]);return redirect()->route('users.show',$userID)->with('success','کاربر ایجاد شد.');}
 public function update(Request $r,string $userID) { Gate::authorize('synapse-users-update');$data=$r->validate(['displayname'=>'nullable|string|max:255','admin'=>'sometimes|boolean','deactivated'=>'sometimes|boolean','locked'=>'sometimes|boolean']);if(!$this->supportsLocked())unset($data['locked']);$this->core->request('PUT','/api/v1/users/'.$this->id($userID),[],$data);$this->audit->record($r,'synapse.user.update','matrix_user',$userID,$data);return back()->with('success','اطلاعات کاربر ذخیره شد.');}
 public function resetPassword(Request $r,string $userID) { Gate::authorize('synapse-users-update');$data=$r->validate(['new_password'=>'required|string|min:12|max:255','logout_devices'=>'sometimes|boolean']);$this->core->request('POST','/api/v1/users/'.$this->id($userID).'/reset-password',[],$data);$this->audit->record($r,'synapse.user.reset_password','matrix_user',$userID,['logout_devices'=>$data['logout_devices']??true]);return back()->with('success','گذرواژه بازنشانی شد.');}
 public function deactivate(Request $r,string $userID) { Gate::authorize('synapse-users-moderate');$data=$r->validate(['erase'=>'sometimes|boolean']);$this->core->request('POST','/api/v1/users/'.$this->id($userID).'/deactivate',[],$data);$this->audit->record($r,'synapse.user.deactivate','matrix_user',$userID,$data);return back()->with('success','حساب غیرفعال شد.');}
 public function suspend(Request $r,string $userID) { Gate::authorize('synapse-users-moderate');$data=$r->validate(['suspend'=>'required|boolean']);$this->core->request('PUT','/api/v1/users/'.$this->id($userID).'/suspend',[],$data);$this->audit->record($r,'synapse.user.suspend','matrix_user',$userID,$data);return back();}
 public function shadowBan(Request $r,string $userID) { Gate::authorize('synapse-users-moderate');$ban=!$r->isMethod('delete')&&!$r->boolean('remove');$this->core->request($ban?'POST':'DELETE','/api/v1/users/'.$this->id($userID).'/shadow-ban');$this->audit->record($r,$ban?'synapse.user.shadow_ban':'synapse.user.shadow_unban','matrix_user',$userID);return back();}
 public function ratelimit(Request $r,string $userID) { Gate::authorize('synapse-users-update');if($r->boolean('remove')){$this->core->request('DELETE','/api/v1/users/'.$this->id($userID).'/ratelimit');$payload=['removed'=>true];}else{$payload=$r->validate(['messages_per_second'=>'required|integer|min:0','burst_count'=>'required|integer|min:0']);$this->core->request('POST','/api/v1/users/'.$this->id($userID).'/ratelimit',[],$payload);}$this->audit->record($r,'synapse.user.ratelimit','matrix_user',$userID,$payload);return back();}
 public function deleteDevice(Request $r,string $userID,string $deviceID) { Gate::authorize('synapse-users-moderate');$this->core->request('DELETE','/api/v1/users/'.$this->id($userID).'/devices/'.rawurlencode($deviceID));$this->audit->record($r,'synapse.user.device.delete','matrix_user',$userID,['device_id'=>$deviceID]);return back();}
 public function deleteMedia(Request $r,string $userID) { Gate::authorize('synapse-users-delete');$result=$this->core->request('DELETE','/api/v1/users/'.$this->id($userID).'/media',$r->only(['limit','order_by','dir']));$this->audit->record($r,'synapse.user.media.delete','matrix_user',$userID,['deleted_total'=>$result['deleted']??null,'possibly_more'=>$result['possibly_more']??false]);return back();}
}
